import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DJVIMu25.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{"title":"Getting Started"},"headers":[],"relativePath":"en/guides/getting-started.md","filePath":"en/guides/getting-started.md","lastUpdated":1786543805000}'),i={name:"en/guides/getting-started.md"};function n(s,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>A fully GUI-driven Minecraft mini-game lobby plugin built for <strong>Spigot / Paper 1.21 – 1.21.6</strong>. All 15 games are bundled inside the main jar — no extra modules needed. Drop it into <code>plugins/</code> and you&#39;re ready to play.</p><div class="tip custom-block"><p class="custom-block-title">Main Class &amp; Version</p><p>Main class: <code>me.nikl.gamebox.GameBox</code> · Version: <code>1.0</code> · Build: Maven shade (dependencies relocated to <code>me.nikl.gamebox.common.*</code>)</p></div><h2 id="inspiration-acknowledgements" tabindex="-1">Inspiration &amp; Acknowledgements <a class="header-anchor" href="#inspiration-acknowledgements" aria-label="Permalink to &quot;Inspiration &amp; Acknowledgements&quot;">​</a></h2><p>JoyMart is <strong>entirely independently designed and developed</strong> by the author. All code, game logic, GUI interactions, and data storage in this repository are original implementations.</p><p>In terms of product shape, gameplay concepts, and user experience, this project draws inspiration from — and pays tribute to — the following two excellent Spigot community projects:</p><ul><li><a href="https://www.spigotmc.org/resources/jukebox-music-plugin.40580/" target="_blank" rel="noreferrer">JukeBox - Music Plugin</a> — Inspired the &quot;music player + NBS song&quot; concept. The built-in <code>MusicPlayer</code> of this project (NBS song parsing + note-block sequence playback) is a from-scratch re-implementation inspired by this work.</li><li><a href="https://www.spigotmc.org/resources/gamebox-inventory-games-collection.37273/" target="_blank" rel="noreferrer">GameBox - Inventory Games Collection</a> — Inspired the overall &quot;aggregate multiple mini-games via a chest GUI&quot; product shape. The 15 games, token system, high-score table, multiplayer invitations, and AI opponents in this project are all independently rewritten and do not reuse any of their code.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The links above point to the SpigotMC resource pages — click to view the original works. Thanks to the original authors for their excellent contributions to the community.</p></div><h2 id="features-at-a-glance" tabindex="-1">Features at a Glance <a class="header-anchor" href="#features-at-a-glance" aria-label="Permalink to &quot;Features at a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Description</th></tr></thead><tbody><tr><td><strong>Pure GUI</strong></td><td>Pick games through chest inventories; players never need to memorize commands.</td></tr><tr><td><strong>15 Built-in Games</strong></td><td>Single-player: 2048, Minesweeper, Whack-a-Mole, Bejeweled, Lottery, Slot Machine, Maze, Snake, Dino Run; Two-player: Battleship, Connect 4, Tic-Tac-Toe, Rock-Paper-Scissors, Chess; Multiplayer: Monopoly (2–3 players, with AI and betting modes).</td></tr><tr><td><strong>Token System</strong></td><td>Built-in JoyMart tokens with optional Vault economy hook (coins).</td></tr><tr><td><strong>High-Score Table</strong></td><td>Automatically records the top score of every game; supports cross-server MySQL sync.</td></tr><tr><td><strong>Two-Player + AI</strong></td><td>Two-player games support inviting a friend or playing against a built-in AI (no waiting for an opponent).</td></tr><tr><td><strong>Configurable Prize Pools</strong></td><td>Lottery / Slot Machine share a prize pool. Admins can add/remove prizes, adjust weights, and configure token/money/command rewards via the in-game GUI.</td></tr><tr><td><strong>Lobby Mode</strong></td><td>Automatically distributes a hotbar shortcut item in configured worlds; clicking it opens the main menu.</td></tr><tr><td><strong>Dual Storage</strong></td><td>YAML files (default) or MySQL (HikariCP connection pool, BungeeCord-ready).</td></tr><tr><td><strong>Custom Events</strong></td><td>Run configured console commands when a player enters / leaves JoyMart.</td></tr><tr><td><strong>Public API</strong></td><td>Exposed via <code>GameBoxAPI</code> or Bukkit ServicesManager for other plugins.</td></tr><tr><td><strong>Hook Support</strong></td><td>PlaceholderAPI, bStats, CalendarEvents (auto-detected).</td></tr><tr><td><strong>Multi-Language</strong></td><td>Built-in English / Chinese / German / Spanish.</td></tr><tr><td><strong>Scoreboard</strong></td><td>During a game, the sidebar shows the current game, score, high score, and tokens.</td></tr></tbody></table><h2 id="installation-build" tabindex="-1">Installation &amp; Build <a class="header-anchor" href="#installation-build" aria-label="Permalink to &quot;Installation &amp; Build&quot;">​</a></h2><h3 id="option-a-build-from-source-recommended" tabindex="-1">Option A: Build from source (recommended) <a class="header-anchor" href="#option-a-build-from-source-recommended" aria-label="Permalink to &quot;Option A: Build from source (recommended)&quot;">​</a></h3><p>Requires <strong>JDK 21+</strong> and <strong>Maven 3.6+</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/myzer121/JoyMart.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JoyMart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>Build output: <code>target/JoyMart-1.0.jar</code></p><h3 id="option-b-use-a-prebuilt-jar" tabindex="-1">Option B: Use a prebuilt jar <a class="header-anchor" href="#option-b-use-a-prebuilt-jar" aria-label="Permalink to &quot;Option B: Use a prebuilt jar&quot;">​</a></h3><p>If you have a release <code>JoyMart-1.0.jar</code>, just drop it into your server&#39;s <code>plugins/</code> directory.</p><h3 id="server-requirements" tabindex="-1">Server Requirements <a class="header-anchor" href="#server-requirements" aria-label="Permalink to &quot;Server Requirements&quot;">​</a></h3><ul><li><strong>Paper / Spigot 1.21 – 1.21.6</strong> (Paper recommended)</li><li><strong>Java 21+</strong></li><li>Optional: <a href="https://www.spigotmc.org/resources/vault.34315/" target="_blank" rel="noreferrer">Vault</a> + any economy plugin</li><li>Optional: <a href="https://github.com/HelpChat/PlaceholderAPI" target="_blank" rel="noreferrer">PlaceholderAPI</a></li><li>Optional: <a href="https://github.com/niklasstern/CalendarEvents" target="_blank" rel="noreferrer">CalendarEvents</a> (seasonal easter eggs)</li></ul><h2 id="first-run" tabindex="-1">First Run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First Run&quot;">​</a></h2><ol><li>Place <code>JoyMart-1.0.jar</code> into <code>plugins/</code>, start the server once to let it generate the default config.</li><li>Edit <a href="./configuration"><code>plugins/JoyMart/config.yml</code></a> as needed (economy, lobby, invitations, sounds, scoreboard, etc.).</li><li>Edit <a href="./configuration"><code>plugins/JoyMart/games.yml</code></a> to toggle each game and configure sub-commands.</li><li>Edit <a href="./configuration"><code>plugins/JoyMart/tokenShop.yml</code></a> to add/remove shop items.</li><li>Run <a href="./commands"><code>/gba reload</code></a> or restart the server.</li><li>Players run <a href="./commands"><code>/gamebox</code></a> to open the main menu.</li></ol><div class="tip custom-block"><p class="custom-block-title">What&#39;s next?</p><ul><li>Browse every game in <a href="./games">Game Modes</a>.</li><li>Learn the full command set in <a href="./commands">Commands &amp; Permissions</a>.</li><li>Tune your server in <a href="./configuration">Configuration Files</a>.</li></ul></div>`,22)])])}const h=t(i,[["render",n]]);export{u as __pageData,h as default};
